/// Binary-search the property for a code point. Defaults to .other.
pub fn propertyOf(codepoint: u21) Property {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const r = ranges[mid];
        if (codepoint < r.start) hi = mid else if (codepoint > r.end) lo = mid + 1 else return r.prop;
    }
    return .other;
}

/// True when there is a grapheme break between two adjacent code points.
/// Implements UAX #29 rules GB3-GB13 except GB11 (emoji ZWJ sequences),
/// which needs the separate Extended_Pictographic property.
pub fn breakBetween(a: Property, b: Property) bool {
    if (a == .cr and b == .lf) return false; // GB3
    if (a == .control or a == .cr or a == .lf) return true; // GB4
    if (b == .control or b == .cr or b == .lf) return true; // GB5
    // GB6-GB8 Hangul
    if (a == .l and (b == .l or b == .v or b == .lv or b == .lvt)) return false;
    if ((a == .lv or a == .v) and (b == .v or b == .t)) return false;
    if ((a == .lvt or a == .t) and b == .t) return false;
    // GB9/GB9a: no break before Extend, ZWJ, or SpacingMark
    if (b == .extend or b == .zwj or b == .spacing_mark) return false;
    // GB9b: no break after Prepend
    if (a == .prepend) return false;
    // GB12/GB13: no break between regional indicators (pairs)
    if (a == .regional_indicator and b == .regional_indicator) return false;
    return true; // GB999
}
